"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["9539"],{44149(e){e.exports=JSON.parse('{"id":"FIN-1079","slug":"benchmarking","term":"Benchmarking","also_known_as":[],"difficulty":"Advanced","definition":"Benchmarking is comparing a business\'s performance, processes or costs with those of competitors, industry averages or recognised best performers, to identify gaps and opportunities for improvement.","explanation":["Benchmarking answers the question: how are we doing compared with others? It can be applied to financial measures, such as profit margins, cost per unit or return on capital, and to operational measures, such as delivery times, customer satisfaction or staff productivity.","For example, a hospital might find that its average cost per patient is 20% higher than similar hospitals. Investigating the difference might reveal longer stays or higher supply costs, pointing to specific areas to improve.","Benchmarking can be internal, comparing different branches or divisions of the same company; competitive, comparing with direct rivals; or functional, comparing a process, such as invoicing, with leading companies in any industry.","It works best when comparisons are genuinely like for like. Differences in size, location, business model or accounting methods can make benchmarks misleading. The goal is to understand why a gap exists, not simply to copy others."],"note":"","total":1500,"prev":{"slug":"benchmark","term":"Benchmark"},"next":{"slug":"beneficial-owner","term":"Beneficial Owner"}}')}}]);